env.GH_AW_VALIDATION_JSON:
{
  "missing_data": {
    "defaultMax": 20,
    "fields": {
      "alternatives": {
        "type": "string",
        "sanitize": true,
        "maxLength": 256
      },
      "context": {
        "type": "string",
        "sanitize": true,
        "maxLength": 256
      },
      "data_type": {
        "type": "string",
        "sanitize": true,
        "maxLength": 128
      },
      "reason": {
        "type": "string",
        "sanitize": true,
        "maxLength": 256
      }
    }
  },
  "missing_tool": {
    "defaultMax": 20,
    "fields": {
      "alternatives": {
        "type": "string",
        "sanitize": true,
        "maxLength": 512
      },
      "reason": {
        "required": true,
        "type": "string",
        "sanitize": true,
        "maxLength": 256
      },
      "tool": {
        "type": "string",
        "sanitize": true,
        "maxLength": 128
      }
    }
  },
  "noop": {
    "defaultMax": 1,
    "fields": {
      "message": {
        "required": true,
        "type": "string",
        "sanitize": true,
        "maxLength": 65000
      }
    }
  },
  "push_repo_memory": {
    "defaultMax": 1,
    "fields": {
      "memory_id": {
        "type": "string",
        "sanitize": true,
        "maxLength": 128
      }
    }
  },
  "report_incomplete": {
    "defaultMax": 5,
    "fields": {
      "details": {
        "type": "string",
        "sanitize": true,
        "maxLength": 65000
      },
      "reason": {
        "required": true,
        "type": "string",
        "sanitize": true,
        "maxLength": 1024
      }
    }
  },
  "upload_artifact": {
    "defaultMax": 10,
    "fields": {
      "filters": {
        "type": "object"
      },
      "path": {
        "type": "string"
      },
      "temporary_id": {
        "type": "string",
        "pattern": "^#?aw_[A-Za-z0-9_]{3,12}$"
      }
    }
  }
}
